svg.script:

// Configuration for the graphing area
const config = {
  centerX: 400,  // Horizontal center of graph in SVG px
  centerY: 200,  // Vertical center of graph in SVG px
  scale: 35,     // How many SVG pixels equal 1 mathematical unit
  rangeX: 9,     // Calculate from x = -9 to x = +9
  step: 0.05     // Resolution: smaller = smoother line, more calculation
};

// Definitions of the math functions
const mathFunctions = {
  'square': (x) => x * x,
  'sine': (x) => Math.sin(x),
  'sqrt': (x) => (x < 0 ? NaN : Math.sqrt(x)), // Return NaN for negative inputs
  'cubic': (x) => x * x * x,
  'abs': (x) => Math.abs(x),
  'exp': (x) => Math.exp(x) // grows very fast
};

// Main plotting function called by buttons
function plot(funcKey) {
  const func = mathFunctions[funcKey];
  if (!func) return;

  let pathData = "";
  let firstPoint = true;

  // Loop through X values from negative to positive range
  for (let x = -config.rangeX; x <= config.rangeX; x += config.step) {

    // Calculate Y based on the selected function
    const mathY = func(x);

    // Skip undefined/imaginary results (like sqrt(-1))
    if (isNaN(mathY) || !isFinite(mathY)) {
        firstPoint = true; // Reset path if we hit a gap (important for sqrt)
        continue; 
    }

    // --- Coordinate Transformation ---
    // Convert mathematical (x,y) to SVG (pixels_x, pixels_y)
    const svgX = config.centerX + (x * config.scale);
    // Subtract mathY because SVG Y-axis goes DOWN, math Y-axis goes UP
    const svgY = config.centerY - (mathY * config.scale);

    // Build SVG Path 'd' attribute command
    if (firstPoint) {
      pathData += `M ${svgX.toFixed(1)} ${svgY.toFixed(1)}`; // Move to start
      firstPoint = false;
    } else {
      pathData += ` L ${svgX.toFixed(1)} ${svgY.toFixed(1)}`; // Line to next
    }
  }

  // Update the DOM
  document.getElementById('graph-path').setAttribute('d', pathData);
  updateActiveButton(funcKey);
}

// UI Helper to highlight selected button
function updateActiveButton(activeKey) {
   const btns = document.getElementsByClassName('btn');
   for(let btn of btns) {
       btn.classList.remove('active');
       if(btn.id === 'btn-' + activeKey) {
           btn.classList.add('active');
       }
   }
}

// Initialize with Sine wave on load
window.onload = function() {
    plot('sine');
};
